// Padrão módulo com IIFE: encapsula um contador privado
const ContadorModulo = (function () {
  let contador = 0; // estado privado, inacessível de fora

  function incrementar() {
    contador += 1;
    return contador;
  }

  function obterValor() {
    return contador;
  }

  return { incrementar, obterValor }; // API pública
})();

ContadorModulo.incrementar();
ContadorModulo.incrementar();
console.log(ContadorModulo.obterValor()); // 2
console.log(ContadorModulo.contador); // undefined - permanece privado

