class GestorConfiguracao {
  static #instancia;

  #definicoes;

  constructor() {
    if (GestorConfiguracao.#instancia) {
      throw new Error("Usa GestorConfiguracao.obterInstancia()");
    }
    this.#definicoes = new Map();
    GestorConfiguracao.#instancia = this;
  }

  static obterInstancia() {
    return GestorConfiguracao.#instancia ?? new GestorConfiguracao();
  }

  definir(chave, valor) {
    this.#definicoes.set(chave, valor);
  }

  obter(chave) {
    return this.#definicoes.get(chave);
  }
}

const config1 = GestorConfiguracao.obterInstancia();
config1.definir("tema", "escuro");

const config2 = GestorConfiguracao.obterInstancia();
console.log(config2.obter("tema")); // "escuro" - mesma instância
console.log(config1 === config2); // true

class Retangulo {
  constructor(largura, altura) {
    this.largura = largura;
    this.altura = altura;
  }
  area() {
    return this.largura * this.altura;
  }
}

class Circulo {
  constructor(raio) {
    this.raio = raio;
  }
  area() {
    return Math.PI * this.raio ** 2;
  }
}

// Factory: o código cliente nunca faz "new Retangulo" ou "new Circulo" diretamente
function criarForma(tipo, medidas) {
  switch (tipo) {
    case "retangulo":
      return new Retangulo(medidas.largura, medidas.altura);
    case "circulo":
      return new Circulo(medidas.raio);
    default:
      throw new Error(`Tipo de forma desconhecido: ${tipo}`);
  }
}

const formas = [
  criarForma("retangulo", { largura: 4, altura: 3 }),
  criarForma("circulo", { raio: 2 }),
];

formas.forEach((forma) => console.log(forma.area().toFixed(2)));

class EmissorDeEventos {
  #ouvintes = new Map(); // evento -> Set de callbacks

  on(evento, callback) {
    if (!this.#ouvintes.has(evento)) {
      this.#ouvintes.set(evento, new Set());
    }
    this.#ouvintes.get(evento).add(callback);
    return () => this.off(evento, callback); // devolve função para cancelar subscrição
  }

  off(evento, callback) {
    this.#ouvintes.get(evento)?.delete(callback);
  }

  emit(evento, dados) {
    this.#ouvintes.get(evento)?.forEach((callback) => callback(dados));
  }
}

const carrinho = new EmissorDeEventos();

const cancelar = carrinho.on("item-adicionado", (item) => {
  console.log(`Novo item: ${item.nome} (${item.preco}€)`);
});

carrinho.emit("item-adicionado", { nome: "Teclado", preco: 45 });
cancelar(); // remove este observador; deixa de ser notificado

function comLog(funcaoOriginal) {
  return function (...args) {
    console.log(`A chamar ${funcaoOriginal.name} com`, args);
    const resultado = funcaoOriginal(...args);
    console.log(`${funcaoOriginal.name} devolveu`, resultado);
    return resultado;
  };
}

function comCronometragem(funcaoOriginal) {
  return function (...args) {
    const inicio = performance.now();
    const resultado = funcaoOriginal(...args);
    console.log(`${funcaoOriginal.name} demorou ${(performance.now() - inicio).toFixed(2)}ms`);
    return resultado;
  };
}

function somar(a, b) {
  return a + b;
}

// Compõe os dois decoradores: cada um acrescenta comportamento, sem tocar em "somar"
const somarDecorado = comLog(comCronometragem(somar));

somarDecorado(2, 3);

const estrategiasDesconto = {
  nenhum: (total) => total,
  estudante: (total) => total * 0.9,
  vip: (total) => total * 0.8,
};

function calcularTotal(total, tipoCliente) {
  const aplicarDesconto = estrategiasDesconto[tipoCliente] ?? estrategiasDesconto.nenhum;
  return aplicarDesconto(total);
}

console.log(calcularTotal(100, "estudante")); // 90
console.log(calcularTotal(100, "vip")); // 80
console.log(calcularTotal(100, "desconhecido")); // 100 - estratégia por omissão

// Nova estratégia sem alterar calcularTotal:
estrategiasDesconto.blackFriday = (total) => total * 0.5;
console.log(calcularTotal(100, "blackFriday")); // 50

