const Carteira = (function () {
  let saldo = 0;

  function depositar(valor) {
    if (valor > 0) {
      saldo += valor;
    }
    return saldo;
  }

  function levantar(valor) {
    if (valor > 0 && valor <= saldo) {
      saldo -= valor;
    }
    return saldo;
  }

  function obterSaldo() {
    return saldo;
  }

  return { depositar, levantar, obterSaldo };
})();

Carteira.depositar(100);
Carteira.levantar(30);
Carteira.levantar(1000); // ignorado, saldo insuficiente
console.log(Carteira.obterSaldo()); // 70
console.log(Carteira.saldo); // undefined

