class EmissorDeEventos {
  #ouvintes = new Map();

  on(evento, callback) {
    if (!this.#ouvintes.has(evento)) {
      this.#ouvintes.set(evento, new Set());
    }
    this.#ouvintes.get(evento).add(callback);
    return () => this.off(evento, callback);
  }

  off(evento, callback) {
    this.#ouvintes.get(evento)?.delete(callback);
  }

  emit(evento, dados) {
    this.#ouvintes.get(evento)?.forEach((callback) => callback(dados));
  }
}

class PrecoAcao extends EmissorDeEventos {
  #precoAtual;

  constructor(precoInicial) {
    super();
    this.#precoAtual = precoInicial;
  }

  atualizarPreco(novoPreco) {
    if (novoPreco === this.#precoAtual) return;
    const anterior = this.#precoAtual;
    this.#precoAtual = novoPreco;
    this.emit("alteracao", { anterior, atual: novoPreco });
  }
}

const acao = new PrecoAcao(100);

acao.on("alteracao", ({ anterior, atual }) => {
  if (atual > anterior) console.log(`Subida: ${anterior} -> ${atual}`);
});

acao.on("alteracao", ({ anterior, atual }) => {
  if (atual < anterior) console.log(`Descida: ${anterior} -> ${atual}`);
});

acao.atualizarPreco(110); // Subida: 100 -> 110
acao.atualizarPreco(95); // Descida: 110 -> 95
acao.atualizarPreco(95); // nada é emitido, preço igual

const estrategiasPagamentoBase = {
  multibanco: (valor) => `Referência Multibanco gerada para ${valor}€`,
  mbway: (valor) => `Pedido MB WAY enviado para ${valor}€`,
  cartao: (valor) => `Pagamento com cartão aprovado: ${valor}€`,
};

function comMedicaoEValidacao(funcaoOriginal) {
  return function (valor) {
    if (typeof valor !== "number" || valor <= 0) {
      throw new Error(`Valor inválido para pagamento: ${valor}`);
    }
    const inicio = performance.now();
    const resultado = funcaoOriginal(valor);
    console.log(`${funcaoOriginal.name} demorou ${(performance.now() - inicio).toFixed(3)}ms`);
    return resultado;
  };
}

const estrategiasPagamento = Object.fromEntries(
  Object.entries(estrategiasPagamentoBase).map(([nome, funcao]) => [
    nome,
    comMedicaoEValidacao(funcao),
  ])
);

function processarPagamento(metodo, valor) {
  const estrategia = estrategiasPagamento[metodo];
  if (!estrategia) {
    throw new Error(`Método de pagamento não suportado: ${metodo}`);
  }
  return estrategia(valor);
}

